"""Flask service exposing sentiment analysis via a local Hugging Face model."""
import os

from flask import Flask, jsonify, request
from transformers import pipeline

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

# Load model once at startup from the local cache.
classifier = pipeline("text-classification", model=MODEL_DIR)


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if data is None:
        return jsonify({"error": "Request body must be valid JSON"}), 400
    if not isinstance(data, dict) or "text" not in data:
        return jsonify({"error": "JSON body must include a 'text' field"}), 400
    text = data["text"]
    if not isinstance(text, str):
        return jsonify({"error": "'text' must be a string"}), 400
    if not text.strip():
        return jsonify({"error": "'text' must be a non-empty string"}), 400

    try:
        results = classifier(text, return_all_labels=True, truncation=True)
    except Exception as exc:
        return jsonify({"error": f"Inference failed: {exc}"}), 500

    scores = {item["label"].lower(): float(item["score"]) for item in results}
    pos = scores.get("positive", 0.0)
    neg = scores.get("negative", 1.0 - pos)
    sentiment_label = "positive" if pos >= neg else "negative"
    return jsonify(
        {
            "sentiment": sentiment_label,
            "confidence": {"positive": pos, "negative": neg},
        }
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)

