"""Convert TF.js shards of DistilBERT SST-2 into model.safetensors (HF layout)."""
import json
import re

import numpy as np
from safetensors.torch import save_file

import torch

TFJS_DIR = "/tmp/tfjs"
DEST = "/app/model_cache/sentiment_model/model.safetensors"
PREFIX = "tf_distil_bert_for_sequence_classification/"


def map_name(n: str) -> str:
    assert n.startswith(PREFIX), n
    n = n[len(PREFIX):]
    if n == "distilbert/embeddings/word_embeddings/weight":
        return "embeddings.word_embeddings.weight"
    if n == "distilbert/embeddings/position_embeddings/embeddings":
        return "embeddings.position_embeddings.weight"
    if n == "distilbert/embeddings/LayerNorm/gamma":
        return "embeddings.LayerNorm.weight"
    if n == "distilbert/embeddings/LayerNorm/beta":
        return "embeddings.LayerNorm.bias"
    if n.startswith("distilbert/transformer/"):
        rest = n[len("distilbert/transformer/"):]
        m = re.match(r"layer_\._(\d+)/(.+)", rest)
        idx, sub = int(m.group(1)), m.group(2)
        sub = sub.replace("/attention/", ".attention.")
        sub = re.sub(r"/ffn/lin(\d)/", r".ffn.lin\1.", sub)
        sub = sub.replace("/sa_layer_norm/", ".sa_layer_norm.")
        sub = sub.replace("/output_layer_norm/", ".output_layer_norm.")
        sub = sub.replace("kernel", "weight").replace("gamma", "weight").replace("beta", "bias")
        return f"encoder.layer.{idx}.{sub}"
    if n.startswith("pre_classifier/"):
        return "pre_classifier." + ("weight" if n.endswith("kernel") else "bias")
    if n.startswith("classifier/"):
        return "classifier." + ("weight" if n.endswith("kernel") else "bias")
    raise ValueError(f"unmapped name: {n}")


def main():
    manifest = json.load(open(f"{TFJS_DIR}/model.json"))["weightsManifest"]
    blob = b""
    for group in manifest:
        for path in group["paths"]:
            with open(f"{TFJS_DIR}/{path}", "rb") as f:
                blob += f.read()
    print(f"total bytes: {len(blob)}")

    tensors = {}
    for group in manifest:
        for w in group["weights"]:
            start, end = w["dataOffsets"]
            arr = np.frombuffer(blob, dtype=np.float32, count=int(np.prod(w["shape"])), offset=start)
            assert w["dtype"] == "float32"
            key = map_name(w["name"])
            tensors[key] = torch.from_numpy(arr.copy()).reshape(w["shape"])
            print(f"{key} {tuple(w['shape'])}")

    save_file(tensors, DEST)
    print("saved", DEST)


if __name__ == "__main__":
    main()

